// 環狀 → 拆成兩條直線：不偷最後一間 / 不偷第一間
// 時間複雜度: O(n)，空間複雜度: O(1)
function rob(nums) {
    const n = nums.length;
    if (n === 1)
        return nums[0];
    const robLine = (start, end) => {
        let prev2 = 0, prev1 = 0;
        for (let i = start; i <= end; i++) {
            const cur = Math.max(prev1, prev2 + nums[i]);
            prev2 = prev1;
            prev1 = cur;
        }
        return prev1;
    };
    return Math.max(robLine(0, n - 2), robLine(1, n - 1));
}

