// 環狀 → 拆成兩條直線：不偷最後一間 / 不偷第一間
// 時間複雜度: O(n)，空間複雜度: O(1)
static int robLine(int* nums, int start, int end) {
    int prev2 = 0, prev1 = 0;
    for (int i = start; i <= end; i++) {
        int take = prev2 + nums[i];
        int cur = take > prev1 ? take : prev1;
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

int rob(int* nums, int numsSize) {
    if (numsSize == 1) return nums[0];
    int a = robLine(nums, 0, numsSize - 2);
    int b = robLine(nums, 1, numsSize - 1);
    return a > b ? a : b;
}

